const now = new Date();
const currentMonth = now.getMonth();
const currentYear = now.getFullYear();
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const lastDayOfMonth = new Date(currentYear, currentMonth + 1, 0);
const offerValidUntil = lastDayOfMonth.toISOString().split('T')[0];

return {
  check_month: monthNames[currentMonth],
  check_year: currentYear,
  batch_id: `upgrade-readiness-${currentYear}-${currentMonth + 1}`,
  generated_at: now.toISOString(),
  offer_valid_until: offerValidUntil,
  weights: {
    frequency:    0.25,
    quality:      0.30,
    completeness: 0.20,
    loyalty:      0.15,
    coo:          0.10,
  },
};

const brand = $input.first().json;
const config = $('Prepare Run Config').first().json;
const daysSinceSignup = Math.floor((Date.now() - new Date(brand.created_at).getTime()) / (1000 * 60 * 60 * 24));

return {
  brand_id:           brand.brand_id,
  brand_name_ar:      brand.brand_name_ar,
  brand_name_en:      brand.brand_name_en || brand.brand_name_ar,
  sector:             brand.sector,
  city:               brand.city_primary,
  tier:               brand.tier,
  total_calendars:    brand.total_calendars_generated || 0,
  completeness_score: brand.completeness_score || 0,
  days_since_signup:  daysSinceSignup,
  dialect:            brand.arabic_dialect,
  primary_channel:    brand.primary_channel,
  batch_id:           config.batch_id,
  offer_valid_until:  config.offer_valid_until,
  weights:            config.weights,
};

const brand = $('Prepare Brand Metrics').first().json;
const posts = $('Supabase: Fetch Brand Posts').all();
const w = brand.weights;

// Frequency Score (25%) — calendars generated (0 cal=0, 1=40, 2=65, 3=80, 4+=100)
const calMap = [0, 40, 65, 80, 100];
const frequencyScore = calMap[Math.min(brand.total_calendars, 4)];

// Quality Score (30%) — avg confidence_score across published posts
const avgConfidence = posts.length > 0
  ? posts.reduce((s, p) => s + (p.json.confidence_score || 70), 0) / posts.length
  : 50;
const qualityScore = Math.min(Math.round(avgConfidence), 100);

// Completeness Score (20%) — brand DNA completeness (stored as 0-100)
const completenessScore = Math.min(Math.round(brand.completeness_score || 0), 100);

// Loyalty Score (15%) — days since account creation
const d = brand.days_since_signup;
let loyaltyScore;
if (d >= 365)      loyaltyScore = 100;
else if (d >= 180) loyaltyScore = 80;
else if (d >= 90)  loyaltyScore = 60;
else if (d >= 30)  loyaltyScore = 30;
else               loyaltyScore = 0;

// COO Score (10%) — proxy: has published posts + complete DNA
const hasPublishedPosts = posts.length > 0 ? 1 : 0;
const hasCompleteDna = (brand.completeness_score || 0) >= 70 ? 1 : 0;
const cooScore = hasPublishedPosts * 50 + hasCompleteDna * 50;

// Weighted composite (0-100)
const totalScore = Math.round(
  frequencyScore    * w.frequency    +
  qualityScore      * w.quality      +
  completenessScore * w.completeness +
  loyaltyScore      * w.loyalty      +
  cooScore          * w.coo
);

// Readiness tier — drives offer personalisation, NOT a gate. All brands proceed.
let readinessTier;
if (totalScore >= 75)      readinessTier = 'highly_ready';
else if (totalScore >= 55) readinessTier = 'ready';
else if (totalScore >= 35) readinessTier = 'potential';
else                       readinessTier = 'not_ready';

const avgPostScore = posts.length > 0
  ? posts.reduce((s, p) => s + (p.json.confidence_score || 70), 0) / posts.length
  : 0;

return {
  brand_id:           brand.brand_id,
  sector:             brand.sector ?? null,
  brand_name_ar:      brand.brand_name_ar,
  brand_name_en:      brand.brand_name_en,
  total_calendars:    brand.total_calendars,
  completeness_score: brand.completeness_score,
  days_since_signup:  brand.days_since_signup,
  posts_count:        posts.length,
  avg_post_score:     Math.round(avgPostScore * 100) / 100,
  batch_id:           brand.batch_id,
  offer_valid_until:  brand.offer_valid_until,
  scores: {
    frequency:    frequencyScore,
    quality:      qualityScore,
    completeness: completenessScore,
    loyalty:      loyaltyScore,
    coo:          cooScore,
  },
  total_score:    totalScore,
  readiness_tier: readinessTier,
};

const scored = $input.first().json;
const tier = scored.readiness_tier;
const cal = scored.total_calendars;

// Bilingual upgrade recommendation personalised by readiness tier
const recommendations = {
  highly_ready: {
    en: `Your brand is generating consistent, high-quality content — you're ready to go pro. Upgrade now and publish automatically to Instagram with ${cal} calendar${cal === 1 ? '' : 's'} already built.`,
    ar: `علامتك التجارية تنتج محتوى متسقًا وعالي الجودة — أنت جاهز للانطلاق باحترافية. رقّي الآن وانشر تلقائيًا على إنستغرام مع ${cal} تقويم${cal === 1 ? '' : 'ات'} جاهز.`,
  },
  ready: {
    en: `Great momentum! You've built ${cal} calendar${cal === 1 ? '' : 's'} with solid quality. Upgrade to auto-publish, unlock all 20 posts per calendar, and get priority support.`,
    ar: `زخم رائع! لقد بنيت ${cal} تقويم${cal === 1 ? '' : 'ات'} بجودة متينة. رقّي للنشر التلقائي وفتح جميع المنشورات وأولوية الدعم.`,
  },
  potential: {
    en: cal > 0
      ? `You're on the right track with ${cal} calendar${cal === 1 ? '' : 's'} generated. Upgrade now to unlock auto-publishing and accelerate your content journey.`
      : 'Your brand foundations are set. Upgrade now to unlock auto-publishing and start your content journey.',
    ar: cal > 0
      ? `أنت على المسار الصحيح مع ${cal} تقويم${cal === 1 ? '' : 'ات'}. رقّي الآن لفتح النشر التلقائي وتسريع رحلة المحتوى الخاصة بك.`
      : 'أسس علامتك التجارية جاهزة. رقّي الآن لفتح النشر التلقائي وابدأ رحلة المحتوى الخاصة بك.',
  },
  not_ready: {
    en: 'Welcome to OGz Studios! Generate your first calendar and unlock auto-publishing, unlimited downloads, and premium AI content — all in one plan.',
    ar: 'مرحبًا في OGz Studios! أنشئ تقويمك الأول وافتح النشر التلقائي والتنزيلات غير المحدودة والمحتوى المتميز — كل ذلك في خطة واحدة.',
  },
};

// Tier-based offer matrix — discount depth rewards usage history
const offers = {
  highly_ready: { en: '20% off your first 3 months', ar: 'خصم 20% على أول 3 أشهر' },
  ready:        { en: '20% off your first month',    ar: 'خصم 20% على أول شهر' },
  potential:    { en: '15% off your first month',    ar: 'خصم 15% على أول شهر' },
  not_ready:    { en: '10% off your first month',    ar: 'خصم 10% على أول شهر' },
};

const rec   = recommendations[tier];
const offer = offers[tier];

const metricsPayload = JSON.stringify({
  total_calendars:       scored.total_calendars,
  avg_post_score:        scored.avg_post_score,
  completeness_score:    scored.completeness_score,
  days_since_signup:     scored.days_since_signup,
  posts_count:           scored.posts_count,
  features_to_highlight: ['auto_publishing', 'unlimited_posts', 'unlimited_calendars', 'priority_support'],
});

const scoresPayload = JSON.stringify(scored.scores);

return {
  brand_id:                   scored.brand_id,
  evaluation_type:            'upgrade_readiness',
  readiness_tier:             tier,
  total_score:                scored.total_score,
  scores:                     scoresPayload,
  metrics:                    metricsPayload,
  upgrade_recommendation:     rec.en,
  upgrade_recommendation_ar:  rec.ar,
  suggested_offer:            offer.en,
  suggested_offer_ar:         offer.ar,
  offer_valid_until:          scored.offer_valid_until,
  offer_status:               'pending',
  batch_id:                   scored.batch_id,
  evaluated_at:               new Date().toISOString(),
};

const scored  = $('Calculate Upgrade Score').first().json;
const offerData = $('Generate Offer Copy').first().json;

return {
  brand_id:           scored.brand_id,
  flow_id:            'N8N-A05',
  request_type:       'upgrade_readiness',
  pipeline_assigned:  'marketing_pipeline',
  agents_dispatch:    { coo: false, ceo: false },
  constraints_applied: {
    evaluation_type: 'upgrade_readiness',
    readiness_tier:  scored.readiness_tier,
    total_score:     scored.total_score,
    all_free_brands: true,
  },
  confidence_mode: 'Standard',
  outcome: JSON.stringify({
    brand_name_ar:  scored.brand_name_ar,
    brand_name_en:  scored.brand_name_en,
    sector:         scored.sector ?? null,
    readiness_tier: scored.readiness_tier,
    total_score:    scored.total_score,
    metrics: {
      completeness_score: scored.completeness_score,
      total_calendars:    scored.total_calendars,
      avg_post_score:     scored.avg_post_score,
      posts_count:        scored.posts_count,
      days_since_signup:  scored.days_since_signup,
      scores:             scored.scores,
    },
    batch_id:       scored.batch_id,
    evaluated_at:   offerData.evaluated_at,
  }),
  timestamp:       offerData.evaluated_at,
};

const allBrands = $input.all();
const config = $('Prepare Run Config').first().json;

const tierCounts = { highly_ready: 0, ready: 0, potential: 0, not_ready: 0 };
allBrands.forEach(b => {
  const outcome = b.json.outcome || '';
  const tier = outcome.replace('offer_generated_', '');
  if (tier in tierCounts) tierCounts[tier]++;
});

return {
  batch_id:          config.batch_id,
  check_month:       config.check_month,
  check_year:        config.check_year,
  total_free_brands: allBrands.length,
  offers_generated:  allBrands.length,
  tier_distribution: tierCounts,
  offer_valid_until: config.offer_valid_until,
  generated_at:      new Date().toISOString(),
};

const report = $input.first().json;
return {
  flow_id:      'N8N-A05',
  anomaly_type: 'upgrade_readiness_report',
  details:      report,
  severity:     report.offers_generated > 0 ? 'INFO' : 'LOW',
  brand_id:     null,
  created_at:   new Date().toISOString(),
};

return {
  flow_id:       'N8N-A05',
  error_type:    'UPGRADE_READINESS_BATCH_FAILED',
  error_message: $input.first().json.message || 'Unknown error',
  batch_id:      $('Prepare Run Config').first().json.batch_id,
  timestamp:     new Date().toISOString(),
};

const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'upgrade_readiness_failed',
  severity:     'error',
  source_flow:  'N8N-A05',
  brand_id:     null,
  message:      e.execution?.error?.message || 'A05 upgrade readiness flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-a05`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};
